import test from 'node:test';
import assert from 'node:assert/strict';
import {validateRequest,validateReport,reserve,accept,requestKey} from './controller.mjs';
import {validate,receive} from './protocol.mjs';
import {hash,digest} from './validation.mjs';
import {controllerFixture,protocolFixture,rebindController,rebindProtocol,finding,blocker,memoryStore} from './fixtures.mjs';
const transport={kind:'synthetic-test-double'};

for(const [name,mutate,code] of [
 ['backend inventory omitted',f=>f.q.evidence.splice(1,1),'missing_layer_evidence'],
 ['cross-layer inventory omitted',f=>f.q.evidence.splice(2,1),'missing_layer_evidence'],
 ['backend mislabeled frontend path',f=>f.q.evidence[1].path='src/backend.txt','evidence_layer'],
 ['unknown token',f=>f.r.coverage[1].references=['packet:'+f.q.packet+'/absent'],'unbound_evidence'],
 ['backend references frontend',f=>f.r.coverage[1].references=f.r.coverage[0].references.slice(),'misreferenced_layer_evidence'],
 ['cross-layer references backend',f=>f.r.coverage[2].references=f.r.coverage[1].references.slice(),'misreferenced_layer_evidence'],
 ['undeclared requirement',f=>f.q.evidence[1].requirements=['unknown'],'evidence_requirement'],
 ['bytes altered',f=>f.q.evidence[1].content+='x','file_binding'],
 ['size altered',f=>f.q.evidence[1].bytes++,'file_binding'],
 ['hash altered',f=>f.q.evidence[1].sha256='f'.repeat(64),'file_binding'],
 ['duplicate token',f=>f.q.evidence[1].id='e1','evidence_identity'],
 ['duplicate path',f=>f.q.evidence[1].path=f.q.evidence[0].path,'evidence_identity'],
 ['unknown inventory field',f=>f.q.evidence[0].approve=true,'schema']
])test('controller rejects '+name,()=>{
 const f=controllerFixture();mutate(f);rebindController(f);
 assert.throws(()=>validateReport(f.q,f.r),new RegExp(code));
});
test('controller rejects stale packet hash despite fresh request key',()=>{
 const f=controllerFixture();f.q.evidence[0].content+='x';f.q.evidence[0].bytes++;f.q.evidence[0].sha256=hash(Buffer.from(f.q.evidence[0].content));f.r.requestKey=requestKey(f.q);
 assert.throws(()=>validateReport(f.q,f.r),/packet_binding/);
});
for(const [name,mutate,code] of [
 ['backend inventory omitted',a=>{const [e]=a[0].files.splice(1,1);a[1].delete(e.path)},'missing_layer_evidence'],
 ['cross-layer inventory omitted',a=>{const [e]=a[0].files.splice(2,1);a[1].delete(e.path)},'missing_layer_evidence'],
 ['backend references frontend',a=>a[3].coverage[1].references=a[3].coverage[0].references.slice(),'misreferenced_layer_evidence'],
 ['cross-layer references frontend',a=>a[3].coverage[2].references=a[3].coverage[0].references.slice(),'misreferenced_layer_evidence'],
 ['cross-layer references backend',a=>a[3].coverage[2].references=a[3].coverage[1].references.slice(),'misreferenced_layer_evidence'],
 ['backend path is src',a=>{const e=a[0].files[1],b=a[1].get(e.path);a[1].delete(e.path);e.path='src/backend.txt';a[1].set(e.path,b);a[3].coverage[1].references=[e.path]},'evidence_layer'],
 ['requirement bound to wrong row',a=>a[0].files[1].requirements=['frontend_behavior'],'evidence_requirement'],
])test('protocol rejects '+name+' with refreshed authority and packet digest',()=>{
 const a=protocolFixture();mutate(a);rebindProtocol(a);
 assert.throws(()=>validate(...a),new RegExp(code));
});
for(const path of ['supabase/config.toml','supabase/seed.sql','supabase/.env','supabase/functions/../.env','supabase/functions/.env','supabase/functions/x/AGENTS.md','supabase/qualification/./receipt.txt']){
 test('both validators reject '+path,()=>{
  const f=controllerFixture();f.q.evidence[1].path=path;rebindController(f);assert.throws(()=>validateReport(f.q,f.r),/unsafe_path/);
  const a=protocolFixture();a[0].files[1].path=path;rebindProtocol(a);assert.throws(()=>validate(...a),/unsafe_path/);
 });
}
for(const path of ['supabase/functions/synthetic/index.ts','supabase/qualification/synthetic-receipt.txt']){
 test('both validators allow bounded '+path,()=>{
  const f=controllerFixture();f.q.evidence[1].path=path;rebindController(f);assert.equal(validateReport(f.q,f.r).outcome,'PASS');
  const a=protocolFixture(),entry=a[0].files[1],bytes=a[1].get(entry.path);a[1].delete(entry.path);entry.path=path;a[1].set(path,bytes);a[3].coverage[1].references=[path];rebindProtocol(a);assert.equal(validate(...a).outcome,'PASS');
 });
}
for(const [target,index] of [['packet',0],['authority',2],['result',3],['origin',4]]){
 for(const key of ['approve','merge','publish','hidden']){
  test('protocol rejects unknown '+target+'.'+key+' before persistence',async()=>{
   const a=protocolFixture();a[index][key]=true;let writes=0;
   assert.throws(()=>validate(...a),/schema/);
   await assert.rejects(receive(a,{putOnce:async()=>{writes++}}),/schema/);assert.equal(writes,0);
  });
 }
}
for(const [target,mutate] of [['coverage',a=>a[3].coverage[0].approve=true],['file',a=>a[0].files[0].approve=true],['finding',a=>{a[3].outcome='FAIL';a[3].coverage[0].status='FAIL';a[3].findings=[{...finding(a[3]),approve:true}]}],['blocker',a=>{a[3].outcome='BLOCKED';a[3].coverage[0].status='BLOCKED';a[3].blockers=[{...blocker(a[3]),approve:true}]}]]){
 test('protocol nested '+target+' exact schema',()=>{const a=protocolFixture();mutate(a);rebindProtocol(a);assert.throws(()=>validate(...a),/schema/)});
}
for(const outcome of ['FAIL','BLOCKED']){
 for(const detail of ['string',{},null]){
  test('protocol rejects non-concrete '+outcome+' detail '+JSON.stringify(detail),()=>{
   const a=protocolFixture();a[3].outcome=outcome;a[3].coverage[0].status=outcome;a[3][outcome==='FAIL'?'findings':'blockers']=[detail];assert.throws(()=>validate(...a),/object|schema/);
  });
 }
}
test('finding evidence must be from its coverage row',()=>{
 const a=protocolFixture();a[3].outcome='FAIL';a[3].coverage[0].status='FAIL';a[3].findings=[{...finding(a[3]),evidence:a[3].coverage[1].references}];assert.throws(()=>validate(...a),/finding_evidence/);
});
test('each failed row needs its own concrete finding',()=>{
 const a=protocolFixture();a[3].outcome='FAIL';a[3].coverage[0].status=a[3].coverage[1].status='FAIL';a[3].findings=[finding(a[3])];assert.throws(()=>validate(...a),/missing_finding/);
});
test('each blocked row needs its own concrete blocker',()=>{
 const a=protocolFixture();a[3].outcome='BLOCKED';a[3].coverage[0].status=a[3].coverage[1].status='BLOCKED';a[3].blockers=[blocker(a[3])];assert.throws(()=>validate(...a),/missing_blocker/);
});
test('same-layer evidence cannot be reused for an undeclared requirement',()=>{
 const f=controllerFixture();f.q.requirements.push('frontend_other');f.q.requirementLayers.frontend_other='frontend';
 const e={...structuredClone(f.q.evidence[0]),id:'e4',path:'docs/other.md',requirements:['frontend_other']};f.q.evidence.push(e);
 f.r.coverage.push({...structuredClone(f.r.coverage[0]),id:'frontend_other'});rebindController(f);assert.throws(()=>validateReport(f.q,f.r),/misreferenced_layer_evidence/);
});
for(const boundary of ['request','result','create']){
 test('accept retains validated snapshot across '+boundary+' adapter mutation',async()=>{
  const {q,r}=controllerFixture(),s=memoryStore();await reserve(s,q);
  const originalQ=structuredClone(q),originalR=structuredClone(r),oldGet=s.get,oldCreate=s.create;
  const mutate=()=>{q.request='attacker';q.evidence[0].content='changed';r.approve=true;r.outcome='FAIL';r.coverage[0].references=[]};
  s.get=async k=>{if(k.startsWith(boundary+'/'))mutate();return oldGet(k)};
  s.create=async(k,v)=>{if(boundary==='create')mutate();return oldCreate(k,v)};
  const d=await accept(s,q,r,transport);
  assert.equal(d.outcome,'PASS');assert.equal(d.approve,false);
  assert.equal(s.rows.get('result/'+originalQ.request),JSON.stringify(originalR));
  assert.equal(d.deliveryKey,digest({request:requestKey(originalQ),result:digest(originalR)}));
  assert.equal(s.rows.has('result/attacker'),false);
 });
}
test('reserve retains original request and embedded bytes across await',async()=>{
 const {q}=controllerFixture(),expected=JSON.stringify(q),s=memoryStore();s.get=async()=>{q.request='changed';q.evidence[0].content='changed';return undefined};
 await reserve(s,q);assert.equal(s.rows.get('request/s1'),expected);assert.equal(s.rows.size,1);
});
test('receive captures result bytes before adapter reentry',async()=>{
 const a=protocolFixture(),expected=JSON.stringify(a[3]);let retained;
 const d=await receive(a,{putOnce:async(k,v)=>{a[3].approve=true;a[3].outcome='FAIL';a[1].get('src/example.jsx').fill(0);retained=v}});
 assert.equal(retained,expected);assert.equal(d.outcome,'PASS');
});

for(const kind of ['controller','protocol']){
 test(kind+' accepts supporting verifier receipt alongside primary layer artifacts',()=>{
  if(kind==='controller'){
   const f=controllerFixture(),content='Synthetic supplemental receipt.';
   f.q.evidence.push({id:'support',path:'verifier/run/receipt.txt',content,bytes:Buffer.byteLength(content),sha256:hash(Buffer.from(content)),role:'supporting',requirements:f.q.requirements.slice()});
   for(const c of f.r.coverage)c.references.push('packet:'+f.q.packet+'/support');
   rebindController(f);assert.equal(validateReport(f.q,f.r).outcome,'PASS');
   f.r.coverage[1].references=['packet:'+f.q.packet+'/support'];
   assert.throws(()=>validateReport(f.q,f.r),/unsupported_pass/);
   f.q.evidence.splice(1,1);rebindController(f);
   assert.throws(()=>validateReport(f.q,f.r),/missing_layer_evidence/);
  }else{
   const a=protocolFixture(),bytes=Buffer.from('Synthetic supplemental receipt.'),path='verifier/run/receipt.txt';
   a[0].files.push({path,bytes:bytes.length,sha256:hash(bytes),role:'supporting',requirements:a[0].requirements.slice()});a[1].set(path,bytes);
   for(const c of a[3].coverage)c.references.push(path);
   rebindProtocol(a);assert.equal(validate(...a).outcome,'PASS');
   a[3].coverage[1].references=[path];assert.throws(()=>validate(...a),/unsupported_pass/);
   const [e]=a[0].files.splice(1,1);a[1].delete(e.path);rebindProtocol(a);
   assert.throws(()=>validate(...a),/missing_layer_evidence/);
  }
 });
}

import {createHash} from 'node:crypto';
const check=(v,c)=>{if(!v)throw Error(c)};
const obj=(v,keys)=>{check(v && Object.getPrototypeOf(v)===Object.prototype,'object');check(Object.keys(v).sort().join('|')===keys.split(' ').sort().join('|'),'schema')};
const id=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,96}$/.test(v);
const sha=v=>typeof v==='string'&&/^[a-f0-9]{40}$/.test(v);
const digest=v=>createHash('sha256').update(JSON.stringify(v)).digest('hex');
const text=v=>typeof v==='string'&&v.length>0&&v.length<=4000;
export function requestKey(request) {return digest(request)}
export function validateRequest(q) {
 obj(q,'version synthetic request candidate packet implementer reviewer model requirements requirementLayers controller');
 check(q.version===1&&q.synthetic===true,'real_activation_disabled');
 check(id(q.request)&&sha(q.candidate)&&sha(q.controller)&&/^[a-f0-9]{64}$/.test(q.packet),'binding');
 check(id(q.implementer)&&id(q.reviewer)&&q.implementer!==q.reviewer&&id(q.model),'independence');
 check(Array.isArray(q.requirements)&&q.requirements.length>=3&&q.requirements.every(id)&&new Set(q.requirements).size===q.requirements.length,'requirements');
 check(q.requirementLayers&&Object.getPrototypeOf(q.requirementLayers)===Object.prototype,'requirement_layers');
 check(Object.keys(q.requirementLayers).sort().join('|')===q.requirements.slice().sort().join('|'),'requirement_layer_binding');
 check(q.requirements.every(k=>['frontend','backend','cross_layer'].includes(q.requirementLayers[k])),'requirement_layer');
 check(['frontend','backend','cross_layer'].every(layer=>Object.values(q.requirementLayers).includes(layer)),'full_stack_required');
}
export function validateReport(q,r) {
 validateRequest(q);
 obj(r,'version synthetic requestKey candidate packet reviewer model outcome coverage findings blockers');
 check(r.version===1&&r.synthetic===true&&r.requestKey===requestKey(q)&&r.candidate===q.candidate&&r.packet===q.packet&&r.reviewer===q.reviewer&&r.model===q.model,'report_binding');
 check(['PASS','FAIL','BLOCKED'].includes(r.outcome),'outcome');
 check(Array.isArray(r.coverage)&&r.coverage.length===q.requirements.length&&new Set(r.coverage.map(x=>x.id)).size===q.requirements.length,'coverage');
 for(const c of r.coverage) {
  obj(c,'id status evidenceClass references');
  check(q.requirements.includes(c.id)&&['PASS','FAIL','BLOCKED','NOT_TESTED'].includes(c.status),'coverage');
  check(['artifact_inspection','independently_reproduced_this_run','supplied_implementation_agent_result','missing_evidence','NOT_TESTED','BLOCKED'].includes(c.evidenceClass),'evidence_class');
  check(Array.isArray(c.references)&&c.references.every(x=>typeof x==='string'&&new RegExp('^packet:'+q.packet+'/[a-zA-Z0-9_-]+$').test(x)),'references');
  if(c.status==='PASS')check(c.references.length>0&&['artifact_inspection','independently_reproduced_this_run'].includes(c.evidenceClass),'unsupported_pass');
 }
 check(Array.isArray(r.findings)&&Array.isArray(r.blockers),'details');
 check(new Set(r.findings.map(x=>x.id)).size===r.findings.length,'duplicate_finding');
 for(const f of r.findings) {
  obj(f,'id requirement severity summary evidence remediation');
  check(id(f.id)&&q.requirements.includes(f.requirement)&&['low','medium','high','critical'].includes(f.severity)&&text(f.summary)&&text(f.remediation),'finding');
  check(Array.isArray(f.evidence)&&f.evidence.length>0&&f.evidence.every(x=>r.coverage.find(c=>c.id===f.requirement).references.includes(x)),'finding_evidence');
 }
 for(const b of r.blockers) {
  obj(b,'kind requirement detail');
  check(['engineering','missing_evidence','owner_decision','permission','disclosure','production','spending'].includes(b.kind)&&q.requirements.includes(b.requirement)&&text(b.detail),'blocker');
 }
 if(r.outcome==='PASS')check(!r.findings.length&&!r.blockers.length&&r.coverage.every(c=>c.status==='PASS'),'false_pass');
 if(r.outcome==='FAIL')check(r.findings.length>0&&r.coverage.some(c=>c.status==='FAIL'),'unsupported_fail');
 if(r.outcome==='BLOCKED')check(r.blockers.length>0&&r.coverage.some(c=>['BLOCKED','NOT_TESTED'].includes(c.status)),'unsupported_blocked');
 return {outcome:r.outcome,synthetic:true,merge:false,approve:false,publish:false,
  proposedAction:r.blockers.some(b=>['owner_decision','permission','disclosure','production','spending'].includes(b.kind))?'owner_required':r.outcome==='PASS'?'continue_authorized_engineering':r.outcome==='FAIL'?'remediate_new_candidate':'continue_other_authorized_work'};
}
// Adapter contract: get(key) and atomic create(key, bytes), never overwrite.
// This module has no credentials, provider calls, GitHub mutations or wakeup API.
// Synthetic lifecycle allows testing crash boundaries before wiring trusted adapters.
export async function reserve(store,q) {
 validateRequest(q); const key='request/'+q.request, bytes=JSON.stringify(q);
 const existing=await store.get(key);
 if(existing!==undefined){check(existing===bytes,'request_conflict');return {created:false,key}}
 try{await store.create(key,bytes);return {created:true,key}}
 catch(e){if(await store.get(key)===bytes)return {created:false,key};throw e}
}
export async function accept(store,q,r,transport) {
 const decision=validateReport(q,r);
 // No caller-controlled verified=true can activate a real review.
 check(transport?.kind==='synthetic-test-double','real_transport_disabled');
 check(await store.get('request/'+q.request)===JSON.stringify(q),'not_reserved');
 const key='result/'+q.request, bytes=JSON.stringify(r), old=await store.get(key);
 if(old!==undefined)check(old===bytes,'result_conflict');
 else try{await store.create(key,bytes)}catch(e){check(await store.get(key)===bytes,'result_conflict')}
 // Result remains durable if delivery crashes. Redelivery uses this exact key.
 return {...decision,deliveryKey:digest({request:requestKey(q),result:digest(r)})};
}

import {createHash} from 'node:crypto';
export const hash = b => createHash('sha256').update(b).digest('hex');
const require = (v, code) => {if(!v) throw Error(code)};
export function validate(packet, files, authority, result, origin) {
 require(/^[a-f0-9]{40}$/.test(packet.candidate),'candidate_not_frozen');
 require(packet.synthetic===true,'real_transport_not_configured');
 require(authority?.candidate===packet.candidate && authority.disclosure===packet.disclosure && JSON.stringify(authority.files)===JSON.stringify(packet.files) && JSON.stringify(authority.requirements)===JSON.stringify(packet.requirements) && JSON.stringify(authority.requirementLayers)===JSON.stringify(packet.requirementLayers),'disclosure_unbound');
 require(Array.isArray(packet.files) && packet.files.length>0 && packet.files.length===files.size,'file_set');
 const seen=new Set();
 for(const f of packet.files) {
  require(typeof f.path==='string' && /^(docs|tests|src|verifier|supabase\/(functions|migrations|qualification))\/[a-zA-Z0-9_./-]+$/.test(f.path) && !f.path.split('/').some(p=>!p || p==='..' || p==='.' || p.startsWith('.')) && !f.path.endsWith('/AGENTS.md') && !seen.has(f.path),'unsafe_path');
  seen.add(f.path);const bytes=files.get(f.path);
  require(Buffer.isBuffer(bytes) && bytes.length===f.bytes && hash(bytes)===f.sha256,'file_binding');
 }
 const digest=hash(JSON.stringify(packet));
 require(origin?.synthetic===true && origin.verified===true && origin.packet===digest,'unverified_origin');
 require(result.packet===digest && result.candidate===packet.candidate && result.request===packet.request && result.synthetic===true,'result_binding');
 require(result.reviewer===origin.reviewer && result.reviewer!==packet.implementer && result.model===origin.model,'self_or_wrong_reviewer');
 require(['PASS','FAIL','BLOCKED'].includes(result.outcome),'outcome');
 require(Array.isArray(packet.requirements) && packet.requirements.length>=3 && new Set(packet.requirements).size===packet.requirements.length,'requirements');
 require(packet.requirementLayers && Object.getPrototypeOf(packet.requirementLayers)===Object.prototype,'requirement_layers');
 require(Object.keys(packet.requirementLayers).sort().join('|')===packet.requirements.slice().sort().join('|'),'requirement_layer_binding');
 require(packet.requirements.every(k=>['frontend','backend','cross_layer'].includes(packet.requirementLayers[k])),'requirement_layer');
 require(['frontend','backend','cross_layer'].every(layer=>Object.values(packet.requirementLayers).includes(layer)),'full_stack_required');
 require(Array.isArray(result.coverage) && result.coverage.length===packet.requirements.length && new Set(result.coverage.map(c=>c.id)).size===packet.requirements.length,'coverage');
 for(const c of result.coverage) {
  require(packet.requirements.includes(c.id) && ['PASS','FAIL','BLOCKED','NOT_TESTED'].includes(c.status),'coverage');
  require(['artifact_inspection','independently_reproduced_this_run','supplied_implementation_agent_result','missing_evidence','NOT_TESTED','BLOCKED'].includes(c.evidence_class),'evidence_class');
  require(Array.isArray(c.references) && c.references.every(p=>seen.has(p)),'unbound_evidence');
  if(c.status==='PASS') require(c.references.length>0 && ['artifact_inspection','independently_reproduced_this_run'].includes(c.evidence_class),'unsupported_pass');
 }
 require(Array.isArray(result.findings) && Array.isArray(result.blockers),'findings');
 if(result.outcome==='PASS') require(!result.findings.length && !result.blockers.length && result.coverage.every(c=>c.status==='PASS'),'false_pass');
 if(result.outcome==='FAIL') require(result.findings.length>0 && result.coverage.some(c=>c.status==='FAIL'),'unsupported_fail');
 if(result.outcome==='BLOCKED') require(result.blockers.length>0 && result.coverage.some(c=>['BLOCKED','NOT_TESTED'].includes(c.status)),'unsupported_blocked');
 return {outcome:result.outcome,action:'synthetic_only',merge:false,approve:false};
}
export async function receive(args, store) {
 const decision=validate(...args);
 const result=args[3];
 await store.putOnce(result.request,JSON.stringify(result));
 return decision;
}

import {check,exact,id,hash,digest,requirements,evidenceBinding,fullInventory,coverage,snapshot} from './validation.mjs';
const sha=v=>typeof v==='string'&&/^[a-f0-9]{40}$/.test(v);
export function requestKey(request){return digest(request)}
export function validateRequest(q){
 exact(q,'version synthetic request candidate packet implementer reviewer model requirements requirementLayers controller evidence');
 check(q.version===2&&q.synthetic===true,'real_activation_disabled');
 check(id(q.request)&&sha(q.candidate)&&sha(q.controller)&&typeof q.packet==='string'&&/^[a-f0-9]{64}$/.test(q.packet),'binding');
 check(id(q.implementer)&&id(q.reviewer)&&q.implementer!==q.reviewer&&id(q.model),'independence');
 requirements(q);
 check(Array.isArray(q.evidence)&&q.evidence.length>0,'evidence_inventory');
 const ids=new Set(),paths=new Set();
 for(const e of q.evidence){
  exact(e,'id path bytes sha256 role requirements content');
  check(id(e.id)&&!ids.has(e.id)&&!paths.has(e.path),'evidence_identity');
  ids.add(e.id);paths.add(e.path);evidenceBinding(e,q);
  check(typeof e.content==='string','file_binding');
  const bytes=Buffer.from(e.content,'utf8');
  check(bytes.toString('utf8')===e.content&&bytes.length===e.bytes&&hash(bytes)===e.sha256,'file_binding');
 }
 check(q.packet===digest(q.evidence),'packet_binding');
 fullInventory(q,q.evidence);
}
export function validateReport(q,r){
 validateRequest(q);
 exact(r,'version synthetic requestKey candidate packet reviewer model outcome coverage findings blockers');
 check(r.version===2&&r.synthetic===true&&r.requestKey===requestKey(q)&&r.candidate===q.candidate&&r.packet===q.packet&&r.reviewer===q.reviewer&&r.model===q.model,'report_binding');
 coverage(q,r,new Map(q.evidence.map(e=>['packet:'+q.packet+'/'+e.id,e])),'evidenceClass');
 return {outcome:r.outcome,synthetic:true,merge:false,approve:false,publish:false,
  proposedAction:r.blockers.some(b=>['owner_decision','permission','disclosure','production','spending'].includes(b.kind))?'owner_required':r.outcome==='PASS'?'continue_authorized_engineering':r.outcome==='FAIL'?'remediate_new_candidate':'continue_other_authorized_work'};
}
// Synthetic-only lifecycle: adapters supply atomic create and exact get.
// No credentials, real transport, wakeup, approval, merge or publication wiring.
export async function reserve(store,request){
 const q=snapshot(request);validateRequest(q);
 const key='request/'+q.request,bytes=JSON.stringify(q);
 const existing=await store.get(key);
 if(existing!==undefined){check(existing===bytes,'request_conflict');return {created:false,key}}
 try{await store.create(key,bytes);return {created:true,key}}
 catch(e){if(await store.get(key)===bytes)return {created:false,key};throw e}
}
export async function accept(store,request,report,transport){
 const q=snapshot(request),r=snapshot(report);
 const decision=validateReport(q,r);
 check(transport?.kind==='synthetic-test-double','real_transport_disabled');
 const requestBytes=JSON.stringify(q),key='result/'+q.request,bytes=JSON.stringify(r);
 const deliveryKey=digest({request:requestKey(q),result:digest(r)});
 check(await store.get('request/'+q.request)===requestBytes,'not_reserved');
 const old=await store.get(key);
 if(old!==undefined)check(old===bytes,'result_conflict');
 else try{await store.create(key,bytes)}catch(e){check(await store.get(key)===bytes,'result_conflict')}
 return {...decision,deliveryKey};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {validateRequest,validateReport,requestKey,reserve,accept} from './controller.mjs';
